            sess.note(f"Square base: base = ({base_scalar.value} * {base_scalar.value}) % {mod_val}")
            new_base = (base_scalar.value * base_scalar.value) % mod_val
            base_scalar.set(new_base)
            sess.note(f"Halve exponent: exponent //= 2")
            exp_scalar.set(exp_scalar.value // 2)

    answer = res_scalar.value
    sess.result(answer)

    trace = sess.to_trace()
