def solve(input_data):
    base = input_data['base']
    exponent = input_data['exponent']
    mod = input_data['mod']
    def fast_pow(x, n):
        if n == 0:
            return 1
        half = fast_pow(x, n // 2)
        if n % 2 == 0:
            return (half * half) % mod
        else:
            return (half * half * x) % mod
    return fast_pow(base, exponent)

