        input_data=input_data,
        pseudocode=[
            "fast_pow(x, n):",
            "  if n == 0: return 1",
            "  half = fast_pow(x, n//2)",
            "  if n % 2 == 0: return (half*half) % mod",
            "  else: return (half*half*x) % mod"
        ]
    )
    base_val = input_data['base']
    exp_val = input_data['exponent']
    mod_val = input_data['mod']
    sess.scalar("base", base_val)
    sess.scalar("exponent", exp_val)
    sess.scalar("mod", mod_val)
    frames = sess.tree("call_stack")

    def fast_pow(x, n):
        with frames.frame(f"fast_pow({x}, {n})"):
            if n == 0:
                sess.note("n=0, return 1")
                return 1
            with sess.step(f"Compute fast_pow({x}, {n//2})"):
                half = fast_pow(x, n // 2)
            if n % 2 == 0:
                res = (half * half) % mod_val
                sess.note(f"even, ({half}*{half})%{mod_val} = {res}")
            else:
                res = (half * half * x) % mod_val
                sess.note(f"odd, ({half}*{half}*{x})%{mod_val} = {res}")
            sess.note(f"Return {res}")
            return res

    answer = fast_pow(base_val, exp_val)
    sess.result(answer)

    trace = sess.to_trace()
    first_frame_encountered = True
    for event in trace["events"]:
        op = event.get("op")
        targets = [t.get("id","") for t in event.get("targets", [])]
        reason = event.get("reason","")
        if op == "create":
            for tid in targets:
                if tid == "base":
                    event["code_line"] = 2
                elif tid == "exponent":
                    event["code_line"] = 3
                elif tid == "mod":
                    event["code_line"] = 4
        elif op == "enter" and event.get("role") == "frame":
            if first_frame_encountered:
                event["code_line"] = 11   # initial call
                first_frame_encountered = False
            else:
                event["code_line"] = 8   # recursive call inside fast_pow
        elif op == "note":
            if "n=0" in reason:
                event["code_line"] = 6
            elif "even" in reason:
                event["code_line"] = 10
            elif "odd" in reason:
                event["code_line"] = 12
            elif "Return" in reason:
                # return statement line depends on parity
                if "even" in reason:
                    event["code_line"] = 10
                elif "odd" in reason:
                    event["code_line"] = 12
                else:
                    event["code_line"] = 10   # fallback
        elif op == "enter" and event.get("role") == "step":
            event["code_line"] = 8   # step wrapping recursive call
        elif event.get("role") == "answer":
            event["code_line"] = 11
    return trace
